INSERT INTO users ("id", "auth0Id", "name", "email", "department")
SELECT su.id::uuid, su."auth0Id", su.name, su.email, d.department
FROM seed_users su
JOIN departments d ON d.code = su.dept_code
ON CONFLICT ("id")
DO NOTHING;

