INSERT INTO xp ("id", "userId", "amount", "reason", "createdAt")
SELECT sx.id::uuid, ui.uid::uuid, sx.amount, r.reason, sx."createdAt"::timestamp
FROM seed_xp sx
JOIN user_idx ui ON ui.idx = sx.user_i
JOIN reasons r ON r.code = sx.reason_code
ON CONFLICT ("id")
DO NOTHING;